def _cs_edit(heading, old_sub, new_point):
    for _h in CHEAT_SHEET:
        if _h['heading'] == heading:
            for _i, _p in enumerate(_h['points']):
                if old_sub in _p:
                    _h['points'][_i] = new_point
                    return
    raise KeyError((heading, old_sub))


def _cs_add(heading, *points):
    for _h in CHEAT_SHEET:
        if _h['heading'] == heading:
            _h['points'].extend(points)
            return
    raise KeyError(heading)


